INSERT INTO `activity_logs` VALUES (1,6,'インタビュー/フィールドワーク: 金沢フィールドワーク','2025-04-12','## 訪問先・対象者\r\n株式会社能作\r\n\r\n## 聞いたこと・見たこと\r\n100万円以上の漆器があった。素材が木で、花色が豪華なものほど高価だった。\r\n\r\n## 気づき\r\n高価な漆器は、簡単に触らことができなかった。やはり、買うことを考えると高価すぎて手が出ない印象だった。\r\n\r\n','インタビュー/フィールドワークで学んだこと、次回に向けての改善点は...',NULL,'2025-04-12 00:43:21','## 訪問先・対象者\r\n株式会社能作\r\n\r\n## 聞いたこと・見たこと\r\n100万円以上の漆器があった。素材が木で、花色が豪華なものほど高価だった。\r\n\r\n## 気づき\r\n高価な漆器は、簡単に触らことができなかった。やはり、買うことを考えると高価すぎて手が出ない印象だった。\r\n\r\n',NULL,NULL),(3,6,'文献調査: aaaaaa','2025-06-10','## 調査した文献\r\naaaaaa\r\n\r\n## 分かったこと\r\n\r\naaaaaaaaaa\r\n## 疑問点・気づき\r\n\r\naaaaaaaaa','今回の調査で学んだこと、次に調べるべきことは...aaaaaaaaaaaa',NULL,'2025-06-10 03:28:26','aaaaaaaa','文献調査',4),(4,6,'探究活動の振り返り: ','2025-06-10','## これまでの進捗\r\naaaa\r\n\r\n## 分かったこと\r\n\r\naaaa\r\n## 課題\r\n\r\naaaa','今後の計画や改善点について...aaaaaa',NULL,'2025-06-10 05:55:00','aaaaa','振り返り',2),(5,19,'計画: ToDoリスト','2025-06-10','## 目標\r\nプリントを終わらせる\r\n\r\n## 具体的な活動計画\r\n\r\n数学のプリントを終わらせる\r\n## スケジュール\r\nできれば今日終わらせる\r\n','計画を実行するにあたっての課題や不安点は...\r\nない。',NULL,'2025-06-10 22:57:54','ToDoリストを立てました','計画',7);
