DROP TABLE IF EXISTS `auto_sync_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `auto_sync_settings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `curriculum_id` int NOT NULL,
  `auto_sync_enabled` tinyint(1) DEFAULT '0',
  `sync_on_curriculum_update` tinyint(1) DEFAULT '1',
  `sync_on_item_change` tinyint(1) DEFAULT '0',
  `conflict_resolution_strategy` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'prompt',
  `sync_delay_minutes` int DEFAULT '5',
  `batch_sync_window` int DEFAULT '30',
  `last_sync_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_curriculum_settings` (`curriculum_id`),
  CONSTRAINT `auto_sync_settings_ibfk_1` FOREIGN KEY (`curriculum_id`) REFERENCES `curriculums` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
