--
-- Table structure for table `student_weaknesses`
--

DROP TABLE IF EXISTS `student_weaknesses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_weaknesses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `student_id` int NOT NULL,
  `subject_id` int DEFAULT NULL,
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subcategory` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weakness_type` enum('concept','skill','knowledge','application') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity_level` int DEFAULT NULL,
  `confidence_score` decimal(3,2) DEFAULT NULL,
  `total_attempts` int DEFAULT NULL,
  `correct_attempts` int DEFAULT NULL,
  `accuracy_rate` decimal(5,2) DEFAULT NULL,
  `last_attempt_at` datetime DEFAULT NULL,
  `improvement_trend` enum('improving','stable','declining') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recommended_actions` json DEFAULT NULL,
  `analysis_data` json DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_id` (`student_id`,`category`,`subcategory`),
  KEY `subject_id` (`subject_id`),
  CONSTRAINT `student_weaknesses_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`),
  CONSTRAINT `student_weaknesses_ibfk_2` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
