INSERT INTO `subjects` VALUES (1,'理科','science','科学的思考を促進し、仮説・実験・結論のプロセスを重視してください。生徒の疑問に対して、観察や実験を通じた探究的な学習を促してください。安全性に配慮し、実験の際の注意事項も含めてください。','科学的な見方・考え方を身に付ける。自然の事物・現象について理解を深める。観察・実験などに関する技能を身に付ける。',NULL,'中学',1,NULL,NULL),(2,'数学','math','論理的思考と段階的な問題解決を支援してください。公式の暗記ではなく、なぜその公式が成り立つのかを理解させてください。実生活での応用例を示し、数学の有用性を伝えてください。','数学的な見方・考え方を身に付ける。数量や図形について理解を深める。問題解決の方法を身に付ける。',NULL,'中学',1,NULL,NULL),(3,'国語','japanese','読解力と表現力の向上を目指してください。文章の構造を意識させ、論理的な文章構成を指導してください。語彙を豊かにし、適切な言葉遣いができるよう支援してください。','言語能力の向上。思考力・判断力・表現力の育成。言語文化への理解を深める。',NULL,'中学',1,NULL,NULL),(4,'社会','social','歴史的背景や地理的要因を考慮し、多角的な視点を提供してください。現代社会との関連性を示し、社会問題への関心を高めてください。批判的思考力を養い、自分の意見を持てるよう促してください。','社会的な見方・考え方を身に付ける。社会的事象について理解を深める。資料活用の技能を身に付ける。',NULL,'中学',1,NULL,NULL),(5,'英語','english','実用的な英語表現を重視し、コミュニケーション能力を高めてください。文法は実際の使用場面と関連付けて説明してください。異文化理解を深め、グローバルな視点を養ってください。','コミュニケーション能力の向上。言語や文化に対する理解を深める。主体的に英語を用いる態度を養う。',NULL,'中学',1,NULL,NULL),(6,'探究','inquiry','生徒の探究心を育み、自主的な学習を支援してください。','課題発見・解決能力の育成',NULL,'中学',1,NULL,NULL),(7,'総合','integrated',NULL,NULL,NULL,NULL,1,'2025-06-19 10:26:04',NULL);
/*!40000 ALTER TABLE `subjects` ENABLE KEYS */;
UNLOCK TABLES;

