  KEY `problem_id` (`problem_id`),
  CONSTRAINT `word_proficiency_records_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`),
  CONSTRAINT `word_proficiency_records_ibfk_2` FOREIGN KEY (`problem_id`) REFERENCES `basic_knowledge_items` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=756 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
